using System;using System.IO;using ScoreModern.RecoveredFragments;
class InputPitchProof {static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),table=File.ReadAllBytes(a[1]),bounds=File.ReadAllBytes(a[2]),tokens=File.ReadAllBytes(a[3]);int count=BitConverter.ToInt16(tokens,0);float[] values=new float[count];Buffer.BlockCopy(tokens,2,values,0,count*4);float staff=BitConverter.ToSingle(ds,0x8780);int clef=BitConverter.ToInt16(ds,0xae02+(int)staff*2);var r=InputPitchRecords.CompileSingleNotes(values,staff,clef,BitConverter.ToSingle(bounds,0),BitConverter.ToSingle(bounds,4),true);int expectedCount=0;while(expectedCount*60+60<=table.Length&&BitConverter.ToSingle(table,expectedCount*60)!=0)expectedCount++;if(expectedCount!=r.Records.Count)throw new Exception("Record count "+r.Records.Count+" != "+expectedCount);for(int n=0;n<r.Records.Count;n++)for(int p=0;p<15;p++){uint actual=BitConverter.ToUInt32(BitConverter.GetBytes(r.Records[n][p]),0),expected=BitConverter.ToUInt32(table,n*60+p*4);if(actual!=expected)throw new Exception("Record "+n+" P"+(p+1)+" "+actual.ToString("x8")+" != "+expected.ToString("x8"));}int maps=0;for(int i=0;i<r.NoteIndices.Count;i++){if(r.NoteIndices[i]!=BitConverter.ToInt16(table,0x2b5c+i*2))throw new Exception("Note map "+i);if(r.ForcedStems[i]!=BitConverter.ToInt16(table,0x2a30+i*2))throw new Exception("Stem map "+i);maps+=2;}Console.WriteLine("PASS "+r.Records.Count*15+" original pitch parameter words and "+maps+" map words.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
